import {hasSensitive} from './admin-permissions.mjs';
import {cardStatuses} from './phone-cards-contract.mjs';
export function createPhoneCardWorkspace({api,h,writable,getUser,notify,localTime}){
 const dialog=document.createElement('dialog');dialog.className='editor wide-editor';dialog.setAttribute('aria-label','手机卡档案与关联');document.body.append(dialog);
 const $=s=>dialog.querySelector(s);let controller,request,timer,serial=0,offset=0,mode='list',selected=null,filters={};
 const close=()=>{controller?.abort();request?.abort();clearTimeout(timer);dialog.close();};dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 const facts=pairs=>`<dl class="record-facts">${pairs.map(([name,value])=>`<div><dt>${h(name)}</dt><dd>${h(value??'未关联')}</dd></div>`).join('')}</dl>`;
 function identityAllowed(){return hasSensitive(getUser(),'resource_identity');}
 async function load(){
  if(!dialog.open)return;request?.abort();request=new AbortController();const signal=AbortSignal.any([controller.signal,request.signal]),current=++serial;
  $('#card-filters').hidden=mode!=='list';$('#card-back').hidden=mode==='list';$('#card-results').textContent='正在读取手机卡…';$('#card-prev').disabled=true;$('#card-next').disabled=true;
  try{
   const data=mode==='list'?await api.phoneCards({...filters,q:$('#card-query').value,status:$('#card-status').value,offset},signal):mode==='detail'?await api.phoneCard(selected,signal):mode==='identity'?await api.phoneCardIdentity(selected,offset,signal):await api.phoneCardHistory(selected,offset,signal);if(signal.aborted||current!==serial)return;
   if(mode==='detail'){
    const r=data;$('#card-results').innerHTML=`<h3>${h(r.cardCode)} · ${h(r.phoneNumber)}</h3>${facts([['运营商',r.carrier||'未填写'],['状态',cardStatuses[r.status]],['使用人',r.userName],['当前设备',r.deviceTag?[r.deviceTag,r.deviceName].join(' · '):null],['所属店铺',r.storeName],['关联运营账号',r.accounts.map(a=>a.name+(a.active?'':'（已停用）')).join('、')||'未关联'],['套餐到期',r.planExpiresOn||'未确认']])}<h3>套餐说明</h3><p class="preserve-text">${h(r.planDescription||'未填写')}</p><h3>普通备注</h3><p class="preserve-text">${h(r.notes||'未填写')}</p><div class="action-row">${writable?`<button class="secondary" data-phone-card-edit="${h(r.id)}">编辑档案与关联</button>`:''}<button class="secondary" data-card-history>档案变更历史</button>${identityAllowed()?'<button class="secondary" data-card-identity>实名资料与历史</button>':'<span class="muted">实名资料需单独授权。</span>'}</div>`;$('#card-caption').textContent='档案版本 '+r.version;return;
   }
   if(!data.rows.length&&offset>0){offset=Math.max(0,offset-50);await load();return;}
   const summary=r=>`${r.phoneNumber} · ${cardStatuses[r.status]} · 使用人：${r.userName||'未关联'} · 设备：${r.deviceTag||'未关联'} · 店铺：${r.storeName||'未关联'} · 账号：${r.accounts.map(a=>a.name).join('、')||'未关联'}`;
   const complete=r=>summary(r)+'\n运营商：'+(r.carrier||'未填写')+'\n套餐说明：'+(r.planDescription||'未填写')+'\n套餐到期：'+(r.planExpiresOn||'未确认')+'\n普通备注：'+(r.notes||'未填写');
   $('#card-results').innerHTML=(mode==='identity'?(writable?`<button class="secondary" data-phone-card-identity-edit="${h(selected)}">登记或变更实名主体</button>`:''):'')+data.rows.map(r=>mode==='list'?`<article class="sample-record"><div><b>${h(r.cardCode)} · ${h(r.phoneNumber)}</b><p>${h(r.carrier||'运营商未填写')} · ${h(cardStatuses[r.status])}</p><p>使用人：${h(r.userName||'未关联')} · 设备：${h(r.deviceTag||'未关联')} · 店铺：${h(r.storeName||'未关联')}</p><p>账号：${h(r.accounts.map(a=>a.name).join('、')||'未关联')}</p></div><div class="action-row"><button class="secondary" data-card-detail="${h(r.id)}">查看档案</button>${writable?`<button class="secondary" data-phone-card-edit="${h(r.id)}">编辑</button>`:''}</div></article>`:mode==='identity'?`<article class="observation"><b>第 ${h(r.version)} 版 · ${h(r.registeredEntity||'待确认')}</b><p>当时卡片：${h(r.cardSnapshot.cardCode)} · ${h(r.cardSnapshot.phoneNumber)}</p><p class="preserve-text">${h(r.reason)}</p><p>${h(r.actor)} · ${h(localTime(r.createdAt))}</p></article>`:`<article class="observation"><b>${r.beforeValue?'变更档案或关联':'登记手机卡'}</b>${r.beforeValue?`<p>变更前：${h(summary(r.beforeValue))}</p>`:''}<p>变更后：${h(summary(r.afterValue))}</p><details><summary>查看完整前后资料</summary>${r.beforeValue?`<h4>变更前</h4><p class="preserve-text">${h(complete(r.beforeValue))}</p>`:''}<h4>变更后</h4><p class="preserve-text">${h(complete(r.afterValue))}</p></details><p class="preserve-text">${h(r.reason)}</p><p>${h(r.actor)} · ${h(localTime(r.createdAt))}</p></article>`).join('')+(data.rows.length?'':'<p class="muted">暂无符合条件的记录。</p>');
   $('#card-caption').textContent=data.total?`${offset+1}–${offset+data.rows.length} / ${data.total} 条`:'0 条记录';$('#card-prev').disabled=offset===0;$('#card-next').disabled=offset+50>=data.total;
  }catch(e){if(!signal.aborted)$('#card-results').textContent=e.status===404?'当前连接尚未部署手机卡功能。':e.message;}
 }
 async function open(value={}){
  if(!hasSensitive(getUser(),'resources')){notify('手机卡档案需要资源管理授权。');return;}
  controller?.abort();request?.abort();clearTimeout(timer);controller=new AbortController();filters={};for(const k of ['deviceId','accountId','storeId'])if(value[k])filters[k]=value[k];selected=value.id||null;mode=selected?'detail':'list';offset=0;
  dialog.innerHTML=`<div class="dialog-header"><h2>手机卡档案与关联</h2><button class="icon-button" data-card-close aria-label="关闭手机卡档案">×</button></div><p class="muted">独立管理卡片、使用人、设备和运营账号关系；实名资料按授权查看。</p><div class="action-row"><button class="secondary" id="card-back" hidden>返回卡片列表</button>${writable?'<button class="primary" data-phone-card-edit="">＋ 登记手机卡</button>':''}${Object.keys(filters).length?'<button class="secondary" id="card-clear-filter">查看全部手机卡</button><span class="muted">当前按来源资源筛选</span>':''}</div><div id="card-filters" class="module-toolbar"><label class="module-search">查找手机卡<input id="card-query" type="search" maxlength="100" placeholder="编号、号码、设备、账号或使用人"></label><label>状态<select id="card-status"><option value="current">在册卡片</option><option value="all">全部状态</option>${Object.entries(cardStatuses).map(([v,t])=>`<option value="${v}">${h(t)}</option>`).join('')}</select></label></div><div id="card-results"></div><div class="pager"><button class="secondary" id="card-prev">上一页</button><span id="card-caption"></span><button class="secondary" id="card-next">下一页</button></div>`;
  $('[data-card-close]').onclick=close;$('#card-back').onclick=()=>{mode='list';offset=0;load();};if($('#card-clear-filter'))$('#card-clear-filter').onclick=()=>open();$('#card-query').oninput=()=>{offset=0;clearTimeout(timer);timer=setTimeout(load,250);};$('#card-status').onchange=()=>{offset=0;load();};$('#card-prev').onclick=()=>{offset=Math.max(0,offset-50);load();};$('#card-next').onclick=()=>{offset+=50;load();};
  $('#card-results').onclick=e=>{const button=e.target.closest('[data-card-detail],[data-card-history],[data-card-identity]');if(!button)return;if(button.hasAttribute('data-card-detail')){selected=button.dataset.cardDetail;mode='detail';}else mode=button.hasAttribute('data-card-identity')?'identity':'history';offset=0;load();};if(!dialog.open)dialog.showModal();await load();
 }
 document.addEventListener('click',e=>{const button=e.target.closest('[data-open-phone-cards]');if(button)open({id:button.dataset.phoneCardId,deviceId:button.dataset.phoneDevice,accountId:button.dataset.phoneAccount,storeId:button.dataset.phoneStore});});
 return {open,refresh:async id=>{if(!dialog.open)return;if(id){selected=id;mode='detail';offset=0;}await load();},close};
}
